45	 public:
46	  enum class Type : uint8_t {
47	    kClear = 0,
48	    kClearColor,
49	    kClearDepth,
50	    kClearStencil,
51	    kCompute,
52	    kDrawArrays,
53	    kDrawRect,
54	    kEntryPoint,
55	    kPatchParameterVertices,
56	    kPipelineProperties,
57	    kProbe,
58	    kProbeSSBO,
59	    kBuffer,
60	    kTolerance,
61	  };
62	
63	  virtual ~Command();
64	
65	  bool IsDrawRect() const { return command_type_ == Type::kDrawRect; }
66	  bool IsDrawArrays() const { return command_type_ == Type::kDrawArrays; }
67	  bool IsCompute() const { return command_type_ == Type::kCompute; }
68	  bool IsProbe() const { return command_type_ == Type::kProbe; }
69	  bool IsProbeSSBO() const { return command_type_ == Type::kProbeSSBO; }
70	  bool IsBuffer() const { return command_type_ == Type::kBuffer; }
71	  bool IsTolerance() const { return command_type_ == Type::kTolerance; }
72	  bool IsClear() const { return command_type_ == Type::kClear; }
73	  bool IsClearColor() const { return command_type_ == Type::kClearColor; }
74	  bool IsClearDepth() const { return command_type_ == Type::kClearDepth; }
75	  bool IsClearStencil() const { return command_type_ == Type::kClearStencil; }
76	  bool IsPatchParameterVertices() const {
77	    return command_type_ == Type::kPatchParameterVertices;
78	  }
79	  bool IsEntryPoint() const { return command_type_ == Type::kEntryPoint; }
80	
81	  ClearCommand* AsClear();
82	  ClearColorCommand* AsClearColor();
83	  ClearDepthCommand* AsClearDepth();
84	  ClearStencilCommand* AsClearStencil();
85	  ComputeCommand* AsCompute();
86	  DrawArraysCommand* AsDrawArrays();
87	  DrawRectCommand* AsDrawRect();
88	  EntryPointCommand* AsEntryPoint();
