15	#ifndef SRC_TOKENIZER_H_
16	#define SRC_TOKENIZER_H_
17	
18	#include <memory>
19	#include <string>
20	
21	#include "amber/result.h"
22	
23	namespace amber {
24	
25	enum class TokenType : uint8_t {
26	  kEOS = 0,
27	  kEOL,
28	  kString,
29	  kInteger,
30	  kDouble,
31	  kHex,
32	};
33	
34	class Token {
35	 public:
36	  Token(TokenType type);
37	  ~Token();
38	
39	  bool IsHex() const { return type_ == TokenType::kHex; }
40	  bool IsInteger() const { return type_ == TokenType::kInteger; }
41	  bool IsDouble() const { return type_ == TokenType::kDouble; }
42	  bool IsString() const { return type_ == TokenType::kString; }
43	  bool IsEOS() const { return type_ == TokenType::kEOS; }
44	  bool IsEOL() const { return type_ == TokenType::kEOL; }
45	
46	  bool IsComma() const {
47	    return type_ == TokenType::kString && string_value_ == ",";
48	  }
49	  bool IsOpenBracket() const {
50	    return type_ == TokenType::kString && string_value_ == "(";
51	  }
52	  bool IsCloseBracket() const {
53	    return type_ == TokenType::kString && string_value_ == ")";
54	  }
55	
56	  void SetNegative() { is_negative_ = true; }
57	  void SetStringValue(const std::string& val) { string_value_ = val; }
58	  void SetUint64Value(uint64_t val) { uint_value_ = val; }
59	  void SetDoubleValue(double val) { double_value_ = val; }
60	
61	  const std::string& AsString() const { return string_value_; }
62	
63	  uint8_t AsUint8() const { return static_cast<uint8_t>(uint_value_); }
64	  uint16_t AsUint16() const { return static_cast<uint16_t>(uint_value_); }
65	  uint32_t AsUint32() const { return static_cast<uint32_t>(uint_value_); }
66	  uint64_t AsUint64() const { return static_cast<uint64_t>(uint_value_); }
67	
68	  int8_t AsInt8() const { return static_cast<int8_t>(uint_value_); }
69	  int16_t AsInt16() const { return static_cast<int16_t>(uint_value_); }
70	  int32_t AsInt32() const { return static_cast<int32_t>(uint_value_); }
71	  int64_t AsInt64() const { return static_cast<int64_t>(uint_value_); }
72	
73	  Result ConvertToDouble();
74	
75	  float AsFloat() const { return static_cast<float>(double_value_); }
76	  double AsDouble() const { return double_value_; }
77	
78	  uint64_t AsHex() const {
79	    return strtoull(string_value_.c_str(), nullptr, 16);
80	  }
81	
82	 private:
83	  TokenType type_;
84	  std::string string_value_;
85	  uint64_t uint_value_ = 0;
86	  double double_value_ = 0.0;
87	  bool is_negative_ = false;
88	};
89	
90	class Tokenizer {
91	 public:
92	  Tokenizer(const std::string& data);
93	  ~Tokenizer();
94	
95	  std::unique_ptr<Token> NextToken();
96	  std::string ExtractToNext(const std::string& str);
97	  size_t GetCurrentLine() const { return current_line_; }
98	
99	 private:
100	  bool IsWhitespace(char ch);
101	  void SkipWhitespace();
102	  void SkipComment();
103	
104	  std::string data_;
105	  size_t current_position_ = 0;
106	  size_t current_line_ = 1;
107	};
108	
109	}  // namespace amber
110	
111	#endif  // SRC_TOKENIZER_H_
