29	Result Token::ConvertToDouble() {
30	  if (IsDouble())
31	    return {};
32	
33	  if (IsString() || IsEOL() || IsEOS())
34	    return Result("Invalid conversion to double");
35	
36	  if (IsInteger()) {
37	    if (is_negative_ || uint_value_ <= std::numeric_limits<int64_t>::max())
38	      double_value_ = static_cast<double>(AsInt64());
39	    else
40	      return Result("uint64_t value too big to fit in double");
41	
42	    uint_value_ = 0;
43	  } else if (IsHex()) {
44	    double_value_ = static_cast<double>(AsHex());
45	    string_value_ = "";
46	  }
47	  type_ = TokenType::kDouble;
48	  return {};
49	}
