51	Tokenizer::Tokenizer(const std::string& data) : data_(data) {}
52	
53	Tokenizer::~Tokenizer() = default;
54	
55	std::unique_ptr<Token> Tokenizer::NextToken() {
56	  SkipWhitespace();
57	  if (current_position_ >= data_.length())
58	    return MakeUnique<Token>(TokenType::kEOS);
59	
60	  if (data_[current_position_] == '#') {
61	    SkipComment();
62	    SkipWhitespace();
63	  }
64	  if (current_position_ >= data_.length())
65	    return MakeUnique<Token>(TokenType::kEOS);
66	
67	  if (data_[current_position_] == '\n') {
68	    ++current_line_;
69	    ++current_position_;
70	    return MakeUnique<Token>(TokenType::kEOL);
71	  }
72	
73	  // If the current position is a , ( or ) then handle it specially as we don't
74	  // want to consume any other characters.
75	  if (data_[current_position_] == ',' || data_[current_position_] == '(' ||
76	      data_[current_position_] == ')') {
77	    auto tok = MakeUnique<Token>(TokenType::kString);
78	    std::string str(1, data_[current_position_]);
79	    tok->SetStringValue(str);
80	    ++current_position_;
81	    return tok;
82	  }
83	
84	  size_t end_pos = current_position_;
85	  while (end_pos < data_.length()) {
86	    if (data_[end_pos] == ' ' || data_[end_pos] == '\n' ||
87	        data_[end_pos] == ')' || data_[end_pos] == ',' ||
88	        data_[end_pos] == '(') {
89	      break;
90	    }
91	    ++end_pos;
92	  }
93	
94	  std::string tok_str =
95	      data_.substr(current_position_, end_pos - current_position_);
96	  current_position_ = end_pos;
97	
98	  // Starts with an alpha is a string.
99	  if (!std::isdigit(tok_str[0]) &&
100	      !(tok_str[0] == '-' && std::isdigit(tok_str[1])) &&
101	      !(tok_str[0] == '.' && std::isdigit(tok_str[1]))) {
102	    // If we've got a continuation, skip over the end of line and get the next
103	    // token.
104	    if (tok_str == "\\") {
105	      if ((current_position_ < data_.length() &&
106	           data_[current_position_] == '\n')) {
107	        ++current_line_;
108	        ++current_position_;
109	        return NextToken();
110	      } else if (current_position_ + 1 < data_.length() &&
111	                 data_[current_position_] == '\r' &&
112	                 data_[current_position_ + 1] == '\n') {
113	        ++current_line_;
114	        current_position_ += 2;
115	        return NextToken();
116	      }
117	    }
118	
119	    auto tok = MakeUnique<Token>(TokenType::kString);
120	    tok->SetStringValue(tok_str);
121	    return tok;
122	  }
123	
124	  // Handle hex strings
125	  if (tok_str.size() > 2 && tok_str[0] == '0' && tok_str[1] == 'x') {
126	    auto tok = MakeUnique<Token>(TokenType::kHex);
127	    tok->SetStringValue(tok_str);
128	    return tok;
129	  }
130	
131	  bool is_double = false;
132	  for (const char ch : tok_str) {
133	    if (ch == '.') {
134	      is_double = true;
135	      break;
136	    }
137	  }
138	
139	  std::unique_ptr<Token> tok;
140	
141	  char* final_pos = nullptr;
142	  if (is_double) {
143	    tok = MakeUnique<Token>(TokenType::kDouble);
144	
145	    double val = strtod(tok_str.c_str(), &final_pos);
146	    tok->SetDoubleValue(val);
147	  } else {
148	    tok = MakeUnique<Token>(TokenType::kInteger);
149	
150	    uint64_t val = strtoull(tok_str.c_str(), &final_pos, 10);
151	    tok->SetUint64Value(static_cast<uint64_t>(val));
152	  }
153	  if (tok_str.size() > 1 && tok_str[0] == '-')
154	    tok->SetNegative();
155	
156	  // If the number isn't the whole token then move back so we can then parse
157	  // the string portion.
158	  auto diff = size_t(final_pos - tok_str.c_str());
159	  if (diff > 0)
160	    current_position_ -= tok_str.length() - diff;
161	
162	  return tok;
163	}
164	
165	std::string Tokenizer::ExtractToNext(const std::string& str) {
166	  size_t pos = data_.find(str, current_position_);
167	  std::string ret;
168	  if (pos == std::string::npos) {
169	    ret = data_.substr(current_position_);
170	    current_position_ = data_.length();
171	  } else {
172	    ret = data_.substr(current_position_, pos - current_position_);
173	    current_position_ = pos;
174	  }
175	
176	  // Account for any new lines in the extracted text so our current line
177	  // number stays correct.
178	  for (const char c : ret) {
179	    if (c == '\n')
180	      ++current_line_;
181	  }
182	
183	  return ret;
184	}
185	
186	bool Tokenizer::IsWhitespace(char ch) {
187	  return ch == '\0' || ch == '\t' || ch == '\r' || ch == 0x0c /* ff */ ||
188	         ch == ' ';
189	}
190	
191	void Tokenizer::SkipWhitespace() {
192	  while (current_position_ < data_.size() &&
193	         IsWhitespace(data_[current_position_])) {
194	    ++current_position_;
195	  }
196	}
197	
198	void Tokenizer::SkipComment() {
199	  while (current_position_ < data_.length() &&
200	         data_[current_position_] != '\n') {
201	    ++current_position_;
202	  }
203	}
